package com.chatsystem.admin.controller;
import com.chatsystem.admin.navigation.*;import com.chatsystem.admin.ui.DisabledControlSupport;import com.chatsystem.admin.ui.cell.AdminMemberCell;import com.chatsystem.shared.model.*;import com.chatsystem.shared.service.AdminService;import javafx.collections.*;import javafx.fxml.FXML;import javafx.scene.control.*;import javafx.scene.layout.StackPane;import java.util.*;
public final class GroupDetailsController implements DisposableController{
 private final AdminService service;private final AdminNavigator navigator;private final ObservableList<ConversationMember> members=FXCollections.observableArrayList();private long id;private final javafx.beans.InvalidationListener refreshListener=o->{if(id>0)present(id);};@FXML private Label nameLabel,descriptionLabel,ownerLabel,createdLabel;@FXML private Button backButton,moderationButton,exportButton;@FXML private StackPane exportWrapper;@FXML private ListView<ConversationMember> memberList;@FXML private ListView<ActivityEvent> activityList;
 public GroupDetailsController(AdminService s,AdminNavigator n){service=s;navigator=n;service.getGroups().addListener(refreshListener);}@FXML private void initialize(){activityList.setCellFactory(v->new com.chatsystem.admin.ui.cell.ActivityEventCell());backButton.setOnAction(e->navigator.navigate(ViewRequest.of(AdminRoute.GROUPS)));moderationButton.setOnAction(e->openModerationHistory());memberList.setItems(members);memberList.setCellFactory(v->new AdminMemberCell(service));DisabledControlSupport.install(exportButton,exportWrapper,exportReason());}
 public void present(long groupId){id=groupId;Conversation g=service.getGroup(id).orElseThrow(()->new IllegalArgumentException("Unknown group "+id));members.setAll(service.getGroupMembers(id));if(nameLabel!=null){nameLabel.setText(g.getName());descriptionLabel.setText(g.getDescription());ownerLabel.setText("Owner: "+service.getUser(g.getCreatedBy()).map(UserAccount::getDisplayName).orElse("Unknown"));createdLabel.setText("Created "+g.getCreatedAt());activityList.setItems(FXCollections.observableArrayList(service.getGroupActivity(id).stream().limit(3).toList()));}}
 public ObservableList<ConversationMember> members(){return FXCollections.unmodifiableObservableList(members);}public void openModerationHistory(){navigator.showModerationForGroup(id);}public String exportReason(){return "Group member export is unavailable in the frontend-only demo.";}
 public void dispose(){service.getGroups().removeListener(refreshListener);}
}
